"""textkit command line: `python3 -m textkit <command> ...`.

Every command is registered with @command. Library functions raise ValueError on bad input;
main() turns that into `error: <message>` on stderr and exit status 2.
"""
import argparse
import csv
import sys

from . import core
from .duration import format_duration, parse_duration
from .mdtable import to_markdown
from .near import closest

COMMANDS = {}


def command(name, help, args=()):
    """Register a subcommand. args is a list of (name_or_flag, add_argument kwargs) pairs."""
    def deco(fn):
        COMMANDS[name] = {"help": help, "args": args, "run": fn}
        return fn
    return deco


@command("shout", "upper-case the text", [("text", {})])
def _shout(a):
    print(core.shout(a.text))
    return 0


@command("count", "count the words in the text", [("text", {})])
def _count(a):
    print(core.count_words(a.text))
    return 0


@command("dur", "convert between seconds and durations like 1h30m", [("value", {})])
def _dur(a):
    v = a.value
    if v.isascii() and v.isdigit():
        print(format_duration(int(v)))
    else:
        print(parse_duration(v))
    return 0


@command("mdtable", "read CSV from stdin and print a markdown table")
def _mdtable(a):
    print(to_markdown(list(csv.reader(sys.stdin))))
    return 0


@command("near", "print the candidate closest to WORD",
         [("word", {}), ("candidates", {"nargs": "+"}), ("--max", {"type": int, "default": 2})])
def _near(a):
    m = closest(a.word, a.candidates, a.max)
    if m is None:
        print("no match", file=sys.stderr)
        return 1
    print(m)
    return 0


@command("commands", "list every command")
def _commands(a):
    for name in sorted(COMMANDS):
        print(name)
    return 0


def main(argv=None):
    p = argparse.ArgumentParser(prog="textkit")
    sub = p.add_subparsers(dest="cmd", required=True)
    for name, c in COMMANDS.items():
        sp = sub.add_parser(name, help=c["help"])
        for flag, kw in c["args"]:
            sp.add_argument(flag, **kw)
    a = p.parse_args(argv)
    try:
        return COMMANDS[a.cmd]["run"](a)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2
import unittest

from textkit.duration import format_duration, parse_duration
from tests.test_cli import run


class DurationTest(unittest.TestCase):
    def test_parse(self):
        for s, n in [("1h30m", 5400), ("45s", 45), ("2h5s", 7205), ("90m", 5400)]:
            self.assertEqual(parse_duration(s), n)

    def test_parse_invalid(self):
        for s in ["", "1x", "30m1h", "1h1h", "1.5h", "h", "1h 30m"]:
            with self.assertRaises(ValueError, msg=s):
                parse_duration(s)

    def test_format(self):
        for n, s in [(5400, "1h30m"), (7205, "2h5s"), (59, "59s"), (0, "0s")]:
            self.assertEqual(format_duration(n), s)
        with self.assertRaises(ValueError):
            format_duration(-1)

    def test_cli(self):
        self.assertEqual(run("dur", "1h30m"), (0, "5400\n", ""))
        self.assertEqual(run("dur", "5400"), (0, "1h30m\n", ""))
        code, out, err = run("dur", "30m1h")
        self.assertEqual(code, 2)
        self.assertTrue(err.startswith("error:"))
        self.assertIn("dur", run("commands")[1].split())
"""The README command table and the registry must agree."""
import pathlib
import re
import unittest

from textkit.cli import COMMANDS

ROOT = pathlib.Path(__file__).resolve().parent.parent


class DocsTest(unittest.TestCase):
    def test_readme_table_matches_registry(self):
        readme = (ROOT / "README.md").read_text()
        table = set(re.findall(r"^\| `([a-z]+)` \|", readme, flags=re.M))
        self.assertEqual(table, set(COMMANDS))

